    "id": "cm-topic-4-7",
    "title": "Section 4.7: Searching — Linear Search & Sentinel Optimization",
    "book_reference": "Lipschutz & Seymour, Data Structures, Revised 4th Ed., Chapter 4: Linear Arrays, Section 4.7, Page 108",
    "topic_tag": "Arrays",
    "content_type": "topic",
    "difficulty": "easy",
    "assigned_date": null,
    "created_by": null,
    "created_at": "2026-09-10T10:00:00.000Z",
