    "id": "cm-problem-4-10",
    "title": "Example 4.10: Binary Search Scale Analysis & Limitations",
    "book_reference": "Lipschutz & Seymour, Data Structures, Revised 4th Ed., Chapter 4: Linear Arrays, Example 4.10, Page 113",
    "topic_tag": "Arrays",
    "content_type": "problem",
    "difficulty": "easy",
    "assigned_date": null,
